import{_ as a,o as n,c as t,a2 as s}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-09-16","description":"","frontmatter":{"title":"AI 动态 · 2026-09-16","date":"2026-09-16T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-09/ai-news-2026-09-16.md","filePath":"news/2026-09/ai-news-2026-09-16.md","lastUpdated":null}'),r={name:"news/2026-09/ai-news-2026-09-16.md"};function i(o,e,l,c,d,p){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-09-16" tabindex="-1">AI 动态 · 2026-09-16 <a class="header-anchor" href="#ai-动态-·-2026-09-16" aria-label="Permalink to &quot;AI 动态 · 2026-09-16&quot;">​</a></h1><blockquote><p>截至 2026-09-16。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="salesforce-不改模型-把浏览器-agent-任务完成率从-43-5-提到-93" tabindex="-1">Salesforce 不改模型，把浏览器 Agent 任务完成率从 43.5% 提到 93% <a class="header-anchor" href="#salesforce-不改模型-把浏览器-agent-任务完成率从-43-5-提到-93" aria-label="Permalink to &quot;Salesforce 不改模型，把浏览器 Agent 任务完成率从 43.5% 提到 93%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VentureBeat AI</span><time datetime="2026-09-16">2026-09-16</time></p><p>Salesforce 研究人员在不改动底层模型的前提下，将 AI Agent 完成浏览器任务的成功率从 43.5% 提升到 93%。提升来自模型之外的工程手段，而非更强的权重。对读者：Agent 效果差时先别急着换模型，检查任务分解、重试与状态管理往往收益更大。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="传-sk-海力士与-intel-洽谈在美国生产存储芯片" tabindex="-1">传 SK 海力士与 Intel 洽谈在美国生产存储芯片 <a class="header-anchor" href="#传-sk-海力士与-intel-洽谈在美国生产存储芯片" aria-label="Permalink to &quot;传 SK 海力士与 Intel 洽谈在美国生产存储芯片&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/5db5fb2ba229.jpg" alt="配图"></p><p>据报道 SK 海力士正与 Intel 洽谈在美国本土生产存储芯片，SK 海力士向 TechCrunch 表示尚未敲定任何计划或安排。AI 算力扩张让 HBM 等存储产能成为地缘与供应链焦点。对读者：关注存储涨价与交期的团队，可把美产产能落地进度纳入硬件采购的风险评估。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/16/sk-hynix-reportedly-in-talks-with-intel-to-build-memory-chips-in-us/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="前-infosys-掌门人的-ai-创业公司再融-5300-万美元" tabindex="-1">前 Infosys 掌门人的 AI 创业公司再融 5300 万美元 <a class="header-anchor" href="#前-infosys-掌门人的-ai-创业公司再融-5300-万美元" aria-label="Permalink to &quot;前 Infosys 掌门人的 AI 创业公司再融 5300 万美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/11f6b78cf84b.jpg" alt="配图"></p><p>这家位于帕洛阿尔托的 AI 创业公司称，产品发布数月内已拿下多份七位数美元的企业合同，并完成新一轮 5300 万美元融资。企业级 AI 服务的订单兑现速度成为资本加注的理由。对读者：评估同类企业 AI 供应商时，别只看融资额，重点核实合同规模与续约情况。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/16/former-infosys-chiefs-ai-startup-adds-50m-to-seed-weeks-after-initial-raise/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="claude-cowork-与聊天合并为统一的-claude" tabindex="-1">Claude Cowork 与聊天合并为统一的 Claude <a class="header-anchor" href="#claude-cowork-与聊天合并为统一的-claude" aria-label="Permalink to &quot;Claude Cowork 与聊天合并为统一的 Claude&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/94d7d732a034.jpg" alt="配图"></p><p>Anthropic 宣布 Claude Cowork 与聊天合并为同一个 Claude，先在 Pro 和 Max 套餐推送。用户把任务交出去，Claude 直接执行，但最终决定权仍保留在人手里。这标志着对话产品与任务执行型 Agent 的边界进一步消失。对读者：重度用户可重新评估套餐价值，同时为「交办任务」的工作流设计好人工复核环节。</p><p class="news-entry-source"><a href="https://claude.com/blog/cowork-is-now-claude" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google-发布-gemini-3-8-live-与-3-8-live-extended-thinking" tabindex="-1">Google 发布 Gemini 3.8 Live 与 3.8 Live Extended Thinking <a class="header-anchor" href="#google-发布-gemini-3-8-live-与-3-8-live-extended-thinking" aria-label="Permalink to &quot;Google 发布 Gemini 3.8 Live 与 3.8 Live Extended Thinking&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/139094fa61c1.png" alt="配图"></p><p>Google DeepMind 推出 Gemini 3.8 Live 和 Gemini 3.8 Live Extended Thinking，称其为目前最先进的实时对话模型，面向自然语音交互场景。Extended Thinking 版本在实时对话中引入更深推理，直接对标 OpenAI 的 GPT-Live 系列。对读者：做语音 Agent 的团队值得尽快实测延迟与打断表现，再决定是否替换现有语音栈。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/introducing-gemini-3-8-live-and-3-8-live-extended-thinking/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="simon-willison-用-gemini-3-8-live-做了个零依赖语音调试网页" tabindex="-1">Simon Willison 用 Gemini 3.8 Live 做了个零依赖语音调试网页 <a class="header-anchor" href="#simon-willison-用-gemini-3-8-live-做了个零依赖语音调试网页" aria-label="Permalink to &quot;Simon Willison 用 Gemini 3.8 Live 做了个零依赖语音调试网页&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/73a442f3effc.webp" alt="配图"></p><p>Simon Willison 借助文档让模型生成一个试用 Gemini 3.8 Live 的 Web UI：可选模型与音色预设、填系统提示词，直接在浏览器里语音对话，并支持打断模型说话。实现不依赖任何库，通过 WebSocket 连接 Google 接口。对读者：想快速验证语音模型效果，可参考这种「无框架最小实现」思路，省去搭脚手架的半天时间。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Sep/15/gemini-live/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="用-amazon-bedrock-agentcore-优化-agent-系统提示词" tabindex="-1">用 Amazon Bedrock AgentCore 优化 Agent 系统提示词 <a class="header-anchor" href="#用-amazon-bedrock-agentcore-优化-agent-系统提示词" aria-label="Permalink to &quot;用 Amazon Bedrock AgentCore 优化 Agent 系统提示词&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/c72a01131f58.png" alt="配图"></p><p>AWS 介绍 AgentCore 的提示词优化机制：把生产环境 trace 转成配置变更建议，验证通过后再上线，并解释其 reflector 引擎原理，给出单 Agent 与子 Agent Reflector 的基准结果。这相当于把提示词调优纳入可回滚的工程流程。对读者：Agent 上线后别只靠人工改 prompt，可考虑用 trace 驱动的自动优化闭环来控质量。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/optimizing-agent-system-prompts-with-amazon-bedrock-agentcore/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="bedrock-提示词缓存-重复上下文可省最多-90-输入成本" tabindex="-1">Bedrock 提示词缓存：重复上下文可省最多 90% 输入成本 <a class="header-anchor" href="#bedrock-提示词缓存-重复上下文可省最多-90-输入成本" aria-label="Permalink to &quot;Bedrock 提示词缓存：重复上下文可省最多 90% 输入成本&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/13a7cd618e35.png" alt="配图"></p><p>AWS 讲解 Bedrock 提示词缓存的六个实用场景，覆盖消息内容、系统提示词、工具定义、混合 TTL、租户隔离与 LangChain 集成，并称重复发送同一上下文时输入 token 成本最多可降 90%。对读者：如果你的应用每次请求都带大段固定上下文，先做缓存改造，通常比换更便宜的模型见效更快。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/optimizing-cost-and-latency-with-amazon-bedrock-prompt-caching/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="stack-overflow-for-agents-更新-隐私改进与-chatgpt-插件" tabindex="-1">Stack Overflow for Agents 更新：隐私改进与 ChatGPT 插件 <a class="header-anchor" href="#stack-overflow-for-agents-更新-隐私改进与-chatgpt-插件" aria-label="Permalink to &quot;Stack Overflow for Agents 更新：隐私改进与 ChatGPT 插件&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Stack Overflow Blog</span><time datetime="2026-09-16">2026-09-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/3891df5277df.png" alt="配图"></p><p>Stack Overflow 回顾面向 Agent 的 API 优先知识交换平台上线三个月的发现，并推出隐私改进与新的 ChatGPT 插件。开发者问答数据正被重新包装成 Agent 可直接调用的知识源。对读者：若你的 Agent 常答错技术细节，可评估接入这类结构化知识接口，比单纯堆上下文更省 token。</p><p class="news-entry-source"><a href="https://stackoverflow.blog/2026/09/15/here-s-what-s-new-on-stack-overflow-for-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
